package GUI;
import Program.service.AuthService; import javafx.geometry.*; import javafx.scene.control.*; import javafx.scene.layout.*;
public class RegisterUI extends StackPane {public RegisterUI(MainUI app,AuthService auth){getStyleClass().add("auth-root");setAlignment(Pos.CENTER);VBox card=new VBox(13);card.setAlignment(Pos.CENTER_LEFT);card.setMaxWidth(400);card.setPrefWidth(400);card.setPadding(new Insets(36));card.getStyleClass().add("auth-card");HBox brand=new HBox(10,UIFactory.logoBadge(),new Label("EXPENSE INTELLIGENCE"));brand.setAlignment(Pos.CENTER_LEFT);((Label)brand.getChildren().get(1)).getStyleClass().add("brand");TextField name=UIFactory.field("Full name"),username=UIFactory.field("Username");PasswordField password=new PasswordField(),confirmation=new PasswordField();password.setPromptText("Password");confirmation.setPromptText("Confirm password");Button create=UIFactory.button("Create Account","primary-button");create.setMaxWidth(Double.MAX_VALUE);Hyperlink back=new Hyperlink("← Back to login");create.setOnAction(e->{try{auth.register(name.getText(),username.getText(),password.getText(),confirmation.getText());UIFactory.info("Account created","Your account is ready. Please sign in.");app.showLogin();}catch(Exception error){UIFactory.error(error.getMessage());}});back.setOnAction(e->app.showLogin());card.getChildren().addAll(brand,UIFactory.title("Create your account"),UIFactory.muted("Your finance data stays on this device."),new Label("FULL NAME"),name,new Label("USERNAME"),username,new Label("PASSWORD"),password,new Label("CONFIRM PASSWORD"),confirmation,create,back);getChildren().add(card);}}
